) OR ( NOT EXISTS ( SELECT 1 FROM crm_youzan_order_map om2 WHERE om2.tenant_id=e.tenant_id AND om2.shop_id=e.shop_id AND om2.external_order_no=e.external_order_no ) AND EXISTS ( SELECT 1 FROM crm_youzan_customer_link customer_link INNER JOIN crm_customer c ON c.tenant_id=customer_link.tenant_id AND c.id=customer_link.customer_id WHERE customer_link.tenant_id=e.tenant_id AND customer_link.shop_id=e.shop_id AND customer_link.external_customer_id=JSON_UNQUOTE(JSON_EXTRACT(e.payload_masked_json,'$.external_customer_id'))
