mapper.select:
SELECT  FROM crm_youzan_event e
WHERE e.tenant_id=#{tenantId} AND e.shop_id=#{shopId} AND e.id IN (
  SELECT MAX(id) FROM crm_youzan_event
  WHERE tenant_id=#{tenantId} AND shop_id=#{shopId}
  GROUP BY external_order_no
)








ORDER BY e.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(DISTINCT e.external_order_no) FROM crm_youzan_event e
WHERE e.tenant_id=#{tenantId} AND e.shop_id=#{shopId} AND e.id IN (
  SELECT MAX(id) FROM crm_youzan_event
  WHERE tenant_id=#{tenantId} AND shop_id=#{shopId}
  GROUP BY external_order_no
)

mapper.update:
UPDATE crm_youzan_event SET process_status=#{status},process_attempts=process_attempts+1,last_error=#{lastError},
  next_retry_at=#{nextRetryAt},processed_at=#{processedAt},order_id=#{orderId},version=version+1
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{version}

mapper.select:
SELECT  FROM crm_youzan_sync_issue i
INNER JOIN crm_youzan_event e ON e.tenant_id=i.tenant_id AND e.id=i.event_id
WHERE i.tenant_id=#{tenantId}
  AND e.shop_id=#{shopId}
  AND e.external_order_no=#{externalOrderNo}
  AND e.id <> #{excludeEventId}
  AND e.event_type IN ('ORDER_PENDING', 'WAIT_PAY')
  AND i.status='OPEN'
  AND i.issue_type IN ('MAPPING_FAILED', 'CUSTOMER_UNRESOLVED', 'RETRY')
ORDER BY i.id FOR UPDATE OF i

SELECT  FROM crm_youzan_sync_issue WHERE tenant_id=#{tenantId}
AND status=#{status}
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

SELECT  FROM crm_youzan_sync_issue i
INNER JOIN crm_youzan_event e ON e.tenant_id=i.tenant_id AND e.id=i.event_id
WHERE i.tenant_id=#{tenantId}
AND i.status=#{status}

ORDER BY i.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM crm_youzan_sync_issue i
INNER JOIN crm_youzan_event e ON e.tenant_id=i.tenant_id AND e.id=i.event_id
WHERE i.tenant_id=#{tenantId}
AND i.status=#{status}

